#!/usr/bin/env python3
from pathlib import Path
import struct,subprocess
repo=Path(__file__).resolve().parents[2];target=repo/'target/animation/shaders';target.mkdir(parents=True,exist_ok=True)
arrays=[]
jobs=[('deform','animation/deform.comp',()),('bounds','animation/bounds.comp',()),('requests','animation/requests.comp',()),('cull','virtual_scene_cull.comp',('GRAPHENE_SKINNED',)),('post_cull','virtual_scene_post_cull.comp',('GRAPHENE_SKINNED',)),('mesh','virtual_scene.mesh',('GRAPHENE_SKINNED',)),('mesh_linear','virtual_scene.mesh',('GRAPHENE_SKINNED','GRAPHENE_LINEAR_COLOR','GRAPHENE_ENVIRONMENT_SHELTER')),('mesh_temporal','virtual_scene.mesh',('GRAPHENE_SKINNED','GRAPHENE_LINEAR_COLOR','GRAPHENE_ENVIRONMENT_SHELTER','GRAPHENE_TEMPORAL')),('cache_dispatch','animation/cache_dispatch.comp',()),('selection','animation/selection.frag',()),('all_vertices','animation/deform.comp',('GRAPHENE_SKIN_ALL',))]
for index,(name,source,flags) in enumerate(jobs):
    dest=target/f'{name}.spv'
    subprocess.run(['glslc','-O','--target-env=vulkan1.3',*['-D'+flag for flag in flags],'-I'+str(repo/'shaders'),str(repo/'shaders'/source),'-o',str(dest)],check=True)
    subprocess.run(['spirv-val','--target-env','vulkan1.3',str(dest)],check=True)
    data=dest.read_bytes();words=struct.unpack('<'+'I'*(len(data)//4),data)
    arrays.append(f'static const uint32_t graphene_animation_shader_{index}[]={{\n'+',\n'.join(','.join(f'0x{x:08x}u' for x in words[i:i+8]) for i in range(0,len(words),8))+'\n};\n')
source='/* Generated by tools/shaders/generate_animation_shaders.py. */\n'+''.join(arrays)
source+='uint32_t graphene_animation_shader_length(uint32_t shader){switch(shader){'+''.join(f'case {i}:return sizeof(graphene_animation_shader_{i})/sizeof(uint32_t);' for i in range(len(jobs)))+'default:return 0;}}\n'
source+='uint32_t graphene_animation_shader_word(uint32_t shader,uint32_t index){if(index>=graphene_animation_shader_length(shader))return 0;switch(shader){'+''.join(f'case {i}:return graphene_animation_shader_{i}[index];' for i in range(len(jobs)))+'default:return 0;}}\n'
source+='uint32_t graphene_animation_f32_bits(float value){uint32_t bits;memcpy(&bits,&value,sizeof bits);return bits;}\n'
(repo/'native/animation_shaders.c').write_text(source)
